#!/usr/bin/env python3
"""
Homicide worldwide, fifth patch (culprits), 17 October 2026. Needs the fourth
homicide patch (homicide_culprits4.py, already applied on main).

Homicide worldwide becomes one layer holding the homicide map's killings and its
figures within countries; the map's crime groups, gangs and organized crime
scores become their own row in a new category; the killings of defenders and
Indigenous peoples go in one category; stand your ground is worldwide.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTE = '## Homicide worldwide, fifth patch (17 October, a separate chat)\n\nNeeds the fourth homicide patch (guards on its heading). Not a numbered round;\nthis note goes at the end of this file.\n\nAsked 17 October: under Destruction > Of individuals > Of humans, Homicide\nworldwide is one layer with its own tick (the `homicides` bundle, retitled),\nholding the homicide map\'s killings (`homicide_worldwide`, now UNODC by country\nand cult killings only), its figures within countries (`homicide_within`) and\nthe four homicide rows that were already in the bundle. The killings of land and\nenvironmental defenders and Indigenous peoples (`killing_indigenous`,\n`defenders`, `brazil_land`) sit in one category of their own. The map\'s groups\nare a new row, `homicide_groups` (registry: homicide.html?part=groups), in a new\ncategory "Crime groups, gangs and cults". Stand your ground is in its own\ncategory and is now worldwide (the map was rebuilt from each country\'s code).\nUnder Invasion of humans the `homicides` bundle copy is unchanged.\n'

DIFF = ""

FILES = ["map/app.js", "map/test.mjs", "pipeline/sitemaps/registry.json"]


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("homicide5: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Homicide worldwide, fourth patch (17 October" not in h.read_text(encoding="utf-8"):
        sys.exit("homicide5: the fourth homicide patch must be applied first (homicide_culprits4.py)")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("homicide5: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", *FILES, check=False)
            sys.exit("homicide5: the diff did not apply:\n" + r.stdout + r.stderr)
        print("homicide5: applied")
    text = h.read_text(encoding="utf-8")
    if NOTE.split("\n", 1)[0] not in text:
        h.write_text(text.rstrip("\n") + "\n\n\n" + NOTE, encoding="utf-8")


if __name__ == "__main__":
    main()
